cat >> typed.py <<'EOF'

MAX_VALUE = 1000
ALLOWED = {"0xAlice000000000000000000000000000000alice"}

def guard_typed(m):
    if m["to"] not in ALLOWED:
        return f"DENY: recipient {m['to'][:14]}... not on the allowlist"
    if m["value"] > MAX_VALUE:
        return f"DENY: value {m['value']} exceeds cap {MAX_VALUE}"
    return "ALLOW"

print("\n=== guardrail with the typed data ===")
for name, m in (("benign", benign), ("drain", drain)):
    print(f"  {name:8} {guard_typed(m)}")
EOF
python3 typed.py

