cat > /tmp/idem.py <<'EOF'
charges, seen = [], {}

def charge(amount, key=None):
    if key is not None:
        if key in seen:
            return f"replayed, no new charge (total {sum(charges)})"
        seen[key] = True
    charges.append(amount)
    return f"charged {amount} (total {sum(charges)})"

print("no key: the response timed out twice, so the client retried twice")
for _ in range(3):
    print("  ", charge(25))

charges.clear(); seen.clear()
print("\nwith a key: same three attempts")
for _ in range(3):
    print("  ", charge(25, key="order-abc-123"))
EOF
python3 /tmp/idem.py
